# Windows 控制台默认可能是 GBK；统一用 UTF-8 输出，避免中文/符号变成乱码或抛错。
for _stream in (sys.stdout, sys.stderr):
    try:
        _stream.reconfigure(encoding="utf-8", errors="replace", line_buffering=True)
    except Exception:
        pass

try:
    import yaml  # PyYAML
except Exception:  # pragma: no cover - 延迟到真正需要时提示
    yaml = None

APP_NAME = "自动化产出简易视频 / main.py"
APP_VERSION = "2.3"

# --auto-topic 未指定领域时的默认方向（越贴近日常生活，命中率越高）
DEFAULT_AUTO_TOPIC_DOMAIN = "日常生活、拖延症、认知偏差、效率陷阱与时间管理"

# ---------------------------------------------------------------------------
# 内嵌提示词与主题
